/**
 * Generated by quail.
 *
 * Storage resilience for https://www.spritecloud.com/agentic-testing. Handles corrupt/absent
 * localStorage / sessionStorage / cookies without blank-screening.
 *
 * Filter: `npx playwright test --grep @kind:storage`
 */
import { test } from '@playwright/test'
import { mobileNav, assertHeadingVisible } from '../prims'

test.describe.configure({ mode: 'parallel' })
test.describe('Spritecloud — storage resilience @ https://www.spritecloud.com/agentic-testing', () => {
  test('@kind:storage @smoke renders with empty storage', async ({ page, context }) => {
    await context.clearCookies()
    await mobileNav(page, 'https://www.spritecloud.com/agentic-testing')
    await page.evaluate(() => { try { localStorage.clear(); sessionStorage.clear() } catch {} })
    await page.reload()
    await assertHeadingVisible(page)
  })

  test('@kind:storage @corrupt page survives garbage in storage', async ({ page }) => {
    await mobileNav(page, 'https://www.spritecloud.com/agentic-testing')
    await page.evaluate(() => {
      try {
        localStorage.setItem('user', '{not_json_at_all}')
        sessionStorage.setItem('theme', '\x00\x01\x02')
      } catch {}
    })
    await page.reload()
    await assertHeadingVisible(page)
  })
})
